CREATE TABLE IF NOT EXISTS environments (id VARCHAR(36) PRIMARY KEY, project_id VARCHAR(36) NOT NULL REFERENCES projects(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id VARCHAR(36) PRIMARY KEY, plan_id VARCHAR(36) NOT NULL REFERENCES plans(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS execution_attempts (approval_id VARCHAR(36) PRIMARY KEY REFERENCES approvals(id) ON DELETE CASCADE, state VARCHAR(20) NOT NULL, execution_id VARCHAR(36));
